{
  "root": "main_stack",
  "state": {
    "weatherMetrics": [
      { "key": "High", "value": "28°C" },
      { "key": "Low", "value": "18°C" },
      { "key": "Humidity", "value": "65%" },
      { "key": "Wind", "value": "15 km/h" },
      { "key": "Chance of Rain", "value": "20%" }
    ],
    "planningTips": [
      { "key": "Best Time to Start", "value": "Early morning (before 9 AM) for popular attractions." },
      { "key": "Hydration", "value": "Carry a reusable water bottle; public fountains are available." },
      { "key": "Sun Protection", "value": "Sunscreen, hat, and sunglasses are recommended." },
      { "key": "Clothing", "value": "Lightweight, breathable fabrics. A light jacket for evenings." },
      { "key": "Transportation", "value": "Walking, Metro, or Vélib' (bike share) are excellent options." }
    ]
  },
  "elements": {
    "main_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "lg",
        "padding": 16
      },
      "children": [
        "weather_section",
        "experiences_section",
        "planning_section",
        "quick_actions_section",
        "sources_section"
      ]
    },
    "weather_section": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md"
      },
      "children": [
        "weather_title",
        "weather_summary_stack",
        "weather_metrics_table"
      ]
    },
    "weather_title": {
      "type": "Text",
      "props": {
        "text": "Paris Weather Snapshot (July 14)",
        "variant": "h2"
      },
      "children": []
    },
    "weather_summary_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "weather_icon",
        "weather_description"
      ]
    },
    "weather_icon": {
      "type": "Icon",
      "props": {
        "name": "../assets/r_000182_01_2_cloud-sun.svg"
      },
      "children": []
    },
    "weather_description": {
      "type": "Text",
      "props": {
        "text": "Paris is expected to have a pleasant summer day with comfortable temperatures, a light breeze, and a low chance of rain. Ideal conditions for enjoying the city's outdoor charm."
      },
      "children": []
    },
    "weather_metrics_table": {
      "type": "Table",
      "props": {
        "columns": [
          { "key": "key", "label": "Metric" },
          { "key": "value", "label": "Value" }
        ],
        "statePath": "/weatherMetrics",
        "domain": "weather",
        "preferredPresentation": "cards",
        "primaryColumn": "key",
        "highlightColumns": ["value"]
      },
      "children": []
    },
    "experiences_section": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md"
      },
      "children": [
        "experiences_title",
        "experience_parks_card",
        "experience_river_cruise_card",
        "experience_historic_districts_card",
        "experience_eiffel_tower_card"
      ]
    },
    "experiences_title": {
      "type": "Text",
      "props": {
        "text": "Recommended Outdoor Experiences",
        "variant": "h3"
      },
      "children": []
    },
    "experience_parks_card": {
      "type": "Card",
      "props": {},
      "children": [
        "parks_icon_title_stack",
        "parks_description",
        "parks_key_activity",
        "parks_comfort_tip",
        "parks_button"
      ]
    },
    "parks_icon_title_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "parks_icon",
        "parks_title"
      ]
    },
    "parks_icon": {
      "type": "Icon",
      "props": {
        "name": "../assets/r_000184_01_3_tree.svg"
      },
      "children": []
    },
    "parks_title": {
      "type": "Text",
      "props": {
        "text": "Stroll Through Parks & Gardens",
        "variant": "h3"
      },
      "children": []
    },
    "parks_description": {
      "type": "Text",
      "props": {
        "text": "Enjoy the serene beauty and shaded paths of Paris's iconic green spaces. Perfect for a morning walk or a relaxed afternoon picnic."
      },
      "children": []
    },
    "parks_key_activity": {
      "type": "Text",
      "props": {
        "text": "Key Activity: Explore Luxembourg Gardens, Tuileries Garden, or Parc des Buttes-Chaumont."
      },
      "children": []
    },
    "parks_comfort_tip": {
      "type": "Text",
      "props": {
        "text": "Comfort Tip: Seek out shaded benches and bring a book for ultimate relaxation."
      },
      "children": []
    },
    "parks_button": {
      "type": "Button",
      "props": {
        "label": "Explore Paris Parks"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.paris.fr/lieux/parcs-et-jardins"
          }
        }
      },
      "children": []
    },
    "experience_river_cruise_card": {
      "type": "Card",
      "props": {},
      "children": [
        "river_cruise_icon_title_stack",
        "river_cruise_description",
        "river_cruise_key_activity",
        "river_cruise_comfort_tip",
        "river_cruise_button"
      ]
    },
    "river_cruise_icon_title_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "river_cruise_icon",
        "river_cruise_title"
      ]
    },
    "river_cruise_icon": {
      "type": "Icon",
      "props": {
        "name": "../assets/r_000184_01_4_water.svg"
      },
      "children": []
    },
    "river_cruise_title": {
      "type": "Text",
      "props": {
        "text": "Seine River Cruise",
        "variant": "h3"
      },
      "children": []
    },
    "river_cruise_description": {
      "type": "Text",
      "props": {
        "text": "Experience Paris from a unique perspective with a refreshing breeze on the water. A great option for midday sightseeing or a romantic evening."
      },
      "children": []
    },
    "river_cruise_key_activity": {
      "type": "Text",
      "props": {
        "text": "Key Activity: Enjoy a Bateaux Mouches or Batobus tour for comprehensive views of landmarks."
      },
      "children": []
    },
    "river_cruise_comfort_tip": {
      "type": "Text",
      "props": {
        "text": "Comfort Tip: Opt for an evening cruise to enjoy cooler temperatures and illuminated monuments."
      },
      "children": []
    },
    "river_cruise_button": {
      "type": "Button",
      "props": {
        "label": "Book a Seine Cruise"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.bateauxmouches.fr/en"
          }
        }
      },
      "children": []
    },
    "experience_historic_districts_card": {
      "type": "Card",
      "props": {},
      "children": [
        "historic_districts_icon_title_stack",
        "historic_districts_description",
        "historic_districts_key_activity",
        "historic_districts_comfort_tip",
        "historic_districts_button"
      ]
    },
    "historic_districts_icon_title_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "historic_districts_icon",
        "historic_districts_title"
      ]
    },
    "historic_districts_icon": {
      "type": "Icon",
      "props": {
        "name": "../assets/r_000184_01_5_map-pin.svg"
      },
      "children": []
    },
    "historic_districts_title": {
      "type": "Text",
      "props": {
        "text": "Explore Historic Districts on Foot",
        "variant": "h3"
      },
      "children": []
    },
    "historic_districts_description": {
      "type": "Text",
      "props": {
        "text": "Wander through charming cobblestone streets and discover hidden gems in areas like Le Marais or Saint-Germain-des-Prés."
      },
      "children": []
    },
    "historic_districts_key_activity": {
      "type": "Text",
      "props": {
        "text": "Key Activity: Self-guided walking tours, boutique shopping, and café hopping."
      },
      "children": []
    },
    "historic_districts_comfort_tip": {
      "type": "Text",
      "props": {
        "text": "Comfort Tip: Wear comfortable shoes and take breaks at shaded cafes."
      },
      "children": []
    },
    "historic_districts_button": {
      "type": "Button",
      "props": {
        "label": "Discover Paris Districts"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.paris.fr/lieux/quartiers-historiques"
          }
        }
      },
      "children": []
    },
    "experience_eiffel_tower_card": {
      "type": "Card",
      "props": {},
      "children": [
        "eiffel_tower_icon_title_stack",
        "eiffel_tower_description",
        "eiffel_tower_key_activity",
        "eiffel_tower_comfort_tip",
        "eiffel_tower_button"
      ]
    },
    "eiffel_tower_icon_title_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "eiffel_tower_icon",
        "eiffel_tower_title"
      ]
    },
    "eiffel_tower_icon": {
      "type": "Icon",
      "props": {
        "name": "../assets/r_000184_01_6_eiffel-tower.svg"
      },
      "children": []
    },
    "eiffel_tower_title": {
      "type": "Text",
      "props": {
        "text": "Visit the Eiffel Tower",
        "variant": "h3"
      },
      "children": []
    },
    "eiffel_tower_description": {
      "type": "Text",
      "props": {
        "text": "An iconic Parisian experience. Consider a morning visit to avoid the midday heat and crowds."
      },
      "children": []
    },
    "eiffel_tower_key_activity": {
      "type": "Text",
      "props": {
        "text": "Key Activity: Ascend to the top for panoramic views, or enjoy the surrounding Champ de Mars."
      },
      "children": []
    },
    "eiffel_tower_comfort_tip": {
      "type": "Text",
      "props": {
        "text": "Comfort Tip: Book tickets in advance to minimize wait times and bring water."
      },
      "children": []
    },
    "eiffel_tower_button": {
      "type": "Button",
      "props": {
        "label": "Plan Your Eiffel Tower Visit"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.toureiffel.paris/en"
          }
        }
      },
      "children": []
    },
    "planning_section": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md"
      },
      "children": [
        "planning_title",
        "planning_tips_table"
      ]
    },
    "planning_title": {
      "type": "Text",
      "props": {
        "text": "Planning Your Day",
        "variant": "h3"
      },
      "children": []
    },
    "planning_tips_table": {
      "type": "Table",
      "props": {
        "columns": [
          { "key": "key", "label": "Tip Category" },
          { "key": "value", "label": "Recommendation" }
        ],
        "statePath": "/planningTips",
        "domain": "generic",
        "preferredPresentation": "cards",
        "primaryColumn": "key",
        "highlightColumns": ["value"]
      },
      "children": []
    },
    "quick_actions_section": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md"
      },
      "children": [
        "quick_actions_title",
        "quick_actions_buttons_stack"
      ]
    },
    "quick_actions_title": {
      "type": "Text",
      "props": {
        "text": "Quick Actions",
        "variant": "h3"
      },
      "children": []
    },
    "quick_actions_buttons_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "button_find_restaurants",
        "button_book_tour",
        "button_public_transport"
      ]
    },
    "button_find_restaurants": {
      "type": "Button",
      "props": {
        "label": "Find Nearby Restaurants"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.google.com/maps/search/restaurants+near+me+paris"
          }
        }
      },
      "children": []
    },
    "button_book_tour": {
      "type": "Button",
      "props": {
        "label": "Book a Guided Tour"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.getyourguide.com/paris-l16/"
          }
        }
      },
      "children": []
    },
    "button_public_transport": {
      "type": "Button",
      "props": {
        "label": "Public Transport Info"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.ratp.fr/en"
          }
        }
      },
      "children": []
    },
    "sources_section": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md"
      },
      "children": [
        "sources_title",
        "sources_buttons_stack"
      ]
    },
    "sources_title": {
      "type": "Text",
      "props": {
        "text": "Sources",
        "variant": "h3"
      },
      "children": []
    },
    "sources_buttons_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "button_paris_tourism",
        "button_weather_forecast"
      ]
    },
    "button_paris_tourism": {
      "type": "Button",
      "props": {
        "label": "Paris Official Tourism Website"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.parisjetaime.com/eng/"
          }
        }
      },
      "children": []
    },
    "button_weather_forecast": {
      "type": "Button",
      "props": {
        "label": "Accurate Weather Forecast"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.meteoparis.com/en"
          }
        }
      },
      "children": []
    }
  }
}
